package com.example.workout.workout.entity; import jakarta.persistence.*; import java.math.BigDecimal; import java.time.OffsetDateTime; import lombok.*;
@Entity @Table(name="workout_track_points") @Getter @Setter @NoArgsConstructor @AllArgsConstructor @Builder(setterPrefix="with") public class WorkoutTrackPointEntity { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @ManyToOne(fetch=FetchType.LAZY,optional=false) @JoinColumn(name="workout_id",nullable=false) private WorkoutEntity workout; @Column(nullable=false) private Integer position; private OffsetDateTime recordedAt; @Column(nullable=false,precision=10,scale=7) private BigDecimal latitude; @Column(nullable=false,precision=10,scale=7) private BigDecimal longitude; @Column(precision=10,scale=2) private BigDecimal elevationMeters; private Integer heartRate; private Integer cadence; private Integer powerWatts; }
